import type { CoursewareTranslateFn } from "../i18n/coursewareRoutesI18n.ts";

/**
 * Slide names the CLI / MCP used to write as a Chinese placeholder before the
 * first slide was left unnamed. Treated like an empty name so the label
 * follows the UI language instead of echoing the stored text.
 */
const LEGACY_AUTO_SLIDE_NAMES = new Set(["第一页"]);

/** True when the stored slide name is empty or a legacy auto-generated placeholder. */
export const isAutoGeneratedSlideName = (name: string | null | undefined): boolean => {
  const trimmed = (name ?? "").trim();
  return trimmed === "" || LEGACY_AUTO_SLIDE_NAMES.has(trimmed);
};

/**
 * Display label for a slide: the stored name, or the localized
 * `coursewareEditor.meta.slideNamePattern` when the name is empty / a legacy
 * placeholder. Never writes back to the scene.
 */
export const resolveSlideDisplayName = (
  name: string | null | undefined,
  index: number,
  t: CoursewareTranslateFn,
): string => {
  if (!isAutoGeneratedSlideName(name)) return (name ?? "").trim();
  return t("coursewareEditor.meta.slideNamePattern", { index: index + 1 });
};
